  #head-sec{display:flex!important;flex-direction:column!important;gap:12px!important;align-items:stretch!important;padding:16px!important}
  #head-sec #Header1{flex:0 0 auto!important;width:100%!important;text-align:center!important}
  #head-sec #Header1 img{margin:0 auto!important}
  #head-sec #HTML505{flex:0 0 auto!important;width:100%!important;max-width:100%!important}
  .index-posts .post-outer .img-wrap{float:right!important;width:165px!important;height:120px!important;margin-left:12px!important}
}
