/* Techno Tour V6 — targeted fixes, homepage-only where appropriate */
/* Force physical placement: ad LEFT, logo RIGHT, independent of language and flex ordering. */
@media screen and (min-width:731px){
  #head-sec{display:grid!important;direction:ltr!important;grid-template-columns:minmax(0,1fr) minmax(190px,290px)!important;grid-template-rows:auto!important;column-gap:22px!important;align-items:center!important;min-height:116px!important;background:$(tt.hybrid.header)!important}
  #head-sec > #HTML505,#head-sec > :has(> #HTML505){grid-column:1!important;grid-row:1!important;justify-self:stretch!important}
