  #head-sec #HTML505{order:0!important;grid-column:1!important;grid-row:1!important;float:none!important;flex:none!important;width:100%!important;max-width:none!important;justify-self:stretch!important}
  #head-sec #Header1{order:1!important;grid-column:2!important;grid-row:1!important;float:none!important;flex:none!important;width:100%!important;max-width:290px!important;justify-self:end!important;text-align:right!important}
  #head-sec #Header1 img{display:block!important;max-width:100%!important;max-height:100px!important;margin-right:0!important;margin-left:auto!important;object-fit:contain!important}
}
