/* Only the category badge IN HOMEPAGE/LABEL CARDS changes; article labels remain untouched. */
.index-posts .post-outer .img-wrap .label-title{position:absolute!important;top:9px!important;right:9px!important;left:auto!important;max-width:78%!important;min-width:0!important;padding:3px 8px!important;margin:0!important;font-family:'Cairo',Tahoma,sans-serif!important;font-size:10px!important;font-weight:700!important;line-height:1.4!important;letter-spacing:0!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;border-radius:5px!important;opacity:1!important;transform:none!important;direction:rtl!important;text-align:right!important}
.index-posts .post-outer .img-wrap:hover .label-title{right:9px!important;left:auto!important;opacity:1!important;transform:none!important}
@media(max-width:560px){.index-posts .post-outer .img-wrap .label-title{font-size:10px!important;max-width:88%!important}}
/* Homepage image frame — full image, not cropped, with a visible loading/fallback state. */
.index-posts .post-outer .tt-smart-thumb{position:relative!important;background:$(tt.hybrid.soft)!important;overflow:hidden!important}
.index-posts .post-outer .tt-smart-thumb img{display:block!important;width:100%!important;height:100%!important;max-width:100%!important;object-fit:contain!important;object-position:center center!important;opacity:0!important;visibility:hidden!important;filter:none!important;transition:opacity .2s ease!important}
.index-posts .post-outer .tt-smart-thumb.tt-image-ready img{opacity:1!important;visibility:visible!important}
.index-posts .post-outer .tt-smart-thumb:hover img{transform:none!important}
.index-posts .post-outer .tt-smart-thumb .tt-image-status{position:absolute;z-index:1;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;font-family:'Cairo',Tahoma,sans-serif;font-size:12px;font-weight:600;color:#536982;background:$(tt.hybrid.soft);padding:12px;pointer-events:none}
.index-posts .post-outer .tt-smart-thumb.tt-image-ready .tt-image-status{display:none!important}
.index-posts .post-outer .tt-smart-thumb .overlay{display:none!important;pointer-events:none!important}
/* Ensure the photo in the full ARTICLE is never cropped; do not change article typography or tags. */
.item-page .post-body img,.static-page .post-body img{max-width:100%!important;width:auto!important;height:auto!important;object-fit:contain!important;object-position:center!important;}
/* The Read More action stays in one position, independent of excerpt and title lengths. */
.index-posts .post-outer{position:relative!important;min-height:217px!important;padding-bottom:59px!important;overflow:hidden!important;--tt-image-width:255px}
.index-posts .post-outer .img-wrap{height:164px!important;width:var(--tt-image-width)!important;float:right!important;margin-left:16px!important}
.index-posts .post-outer .read-more{position:absolute!important;bottom:14px!important;right:calc(var(--tt-image-width) + 30px)!important;left:auto!important;float:none!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;white-space:nowrap!important;margin:0!important;min-width:110px!important;min-height:32px!important;font-size:12px!important;padding:5px 13px!important;line-height:1.6!important}
@media(min-width:731px) and (max-width:980px){.index-posts .post-outer{--tt-image-width:190px}}
@media(max-width:730px){.index-posts .post-outer{--tt-image-width:165px}.index-posts .post-outer .img-wrap{height:120px!important}}
@media(max-width:490px){.index-posts .post-outer{--tt-image-width:100%;padding-bottom:58px!important}.index-posts .post-outer .img-wrap{float:none!important;width:100%!important;height:auto!important;aspect-ratio:16/9!important;margin:0 0 12px!important}.index-posts .post-outer .read-more{right:13px!important;bottom:14px!important}}
/* Remove permanent homepage illumination; illuminate exactly the URL visitors are viewing. */
#menu-bar .menu-bar ul li>a.home{background:transparent!important;color:$(tt.hybrid.text)!important}
#menu-bar .menu-bar ul li>a.tt-current{background:linear-gradient(120deg,$(keycolor),$(step.color))!important;color:#fff!important;box-shadow:inset 0 -3px 0 rgba(255,255,255,.32)!important}
#menu-bar .menu-bar ul li>a:hover:not(.tt-current){background:rgba(255,255,255,.12)!important;color:#fff!important}
#menu-bar .menu-bar ul li>a.tt-current:hover{filter:brightness(1.03)!important}


/* =============================================================
