 #head-sec{position:relative!important;display:block!important;direction:rtl!important;min-height:132px!important;padding:18px 20px!important;background:$(tt.hybrid.header)!important;overflow:hidden!important}
 #head-sec #Header1{position:absolute!important;top:50%!important;right:20px!important;left:auto!important;transform:translateY(-50%)!important;float:none!important;display:block!important;width:275px!important;max-width:275px!important;min-height:0!important;margin:0!important;z-index:2!important;text-align:right!important}
