 #head-sec #HTML505{display:block!important;position:relative!important;top:auto!important;right:auto!important;left:auto!important;float:none!important;transform:none!important;flex:none!important;min-height:90px!important;width:calc(100% - 307px)!important;max-width:none!important;margin:0 307px 0 0!important;text-align:center!important;padding:0!important;border:0!important;box-shadow:none!important;background:transparent!important}
