 #head-sec{display:flex!important;direction:rtl!important;flex-direction:column!important;align-items:center!important;position:relative!important;gap:8px!important;padding:15px 12px!important;background:$(tt.hybrid.header)!important;min-height:0!important}
 #head-sec #Header1{position:static!important;transform:none!important;float:none!important;order:0!important;display:block!important;width:100%!important;max-width:100%!important;flex:0 0 auto!important;margin:0!important;text-align:center!important}
 #head-sec #Header1 img{margin:auto!important;max-width:260px!important;height:auto!important}
 #head-sec #HTML505{position:static!important;float:none!important;order:1!important;display:block!important;transform:none!important;width:100%!important;max-width:100%!important;margin:0!important;min-height:0!important;flex:0 0 auto!important;text-align:center!important;background:transparent!important}
 #head-sec #HTML505:has(.tt-header-ad-content:empty){display:none!important}
}
/* Keep native article images visible by default — never require a script
