.index-posts .post-outer .tt-smart-thumb img,.index-posts .post-outer .tt-smart-thumb:not(.tt-image-ready) img{display:block!important;opacity:1!important;visibility:visible!important;width:100%!important;height:100%!important;max-width:100%!important;object-fit:contain!important;object-position:center center!important;filter:none!important}
.index-posts .post-outer .tt-smart-thumb .tt-image-status{display:none!important;position:absolute!important;inset:0!important;z-index:2!important;align-items:center!important;justify-content:center!important;background:$(tt.hybrid.soft)!important;color:#586C86!important;text-align:center!important;font-family:'Cairo',Tahoma,sans-serif!important;font-size:12px!important;font-weight:500!important}
.index-posts .post-outer .tt-smart-thumb.tt-image-loading .tt-image-status,.index-posts .post-outer .tt-smart-thumb.tt-image-missing .tt-image-status,.index-posts .post-outer .tt-smart-thumb:not(:has(img)) .tt-image-status{display:flex!important}
