  margin:0!important;padding:0!important;
  display:block!important;text-align:center!important;
}
.tt-v8-masthead #Header1{
  display:block!important;float:none!important;position:static!important;
  width:100%!important;max-width:100%!important;
  transform:none!important;flex:none!important;
  min-width:0!important;margin:0!important;padding:0!important;
  text-align:right!important;background:transparent!important;
}
.tt-v8-masthead #Header1 .logo,.tt-v8-masthead #Header1 .img-logo{
  display:block!important;text-align:right!important;direction:rtl!important;
  margin:0!important;padding:0!important;
}
.tt-v8-masthead #Header1 img{
  width:auto!important;height:auto!important;max-width:100%!important;
  max-height:92px!important;object-fit:contain!important;
  display:block!important;margin:0!important;
}
.tt-v8-masthead #HTML505,.tt-v8-masthead #HTML505 .widget-content,
.tt-v8-masthead #HTML505 .tt-header-ad-content,
.tt-v8-masthead .section,.tt-v8-masthead .widget{
  background:transparent!important;background-image:none!important;
  border:none!important;box-shadow:none!important;
}
.tt-v8-masthead #HTML505{
  display:block!important;float:none!important;position:static!important;
  max-width:100%!important;width:100%!important;
  min-height:0!important;margin:0!important;padding:0!important;
  text-align:center!important;transform:none!important;
}
.tt-v8-masthead #HTML505 .tt-header-ad-content:empty{display:none!important}
.tt-v8-masthead #HTML302{display:none!important}
@media screen and (max-width:760px){
  .tt-v8-masthead{grid-template-columns:minmax(0,1fr)!important;grid-template-rows:auto auto!important;gap:8px!important;text-align:center!important;padding:14px 12px!important;min-height:0!important}
  .tt-v8-masthead > #tt_v8_brand{grid-column:1!important;grid-row:1!important;text-align:center!important}
  .tt-v8-masthead > #tt_v8_ad{grid-column:1!important;grid-row:2!important}
  .tt-v8-masthead #Header1,.tt-v8-masthead #Header1 .logo,.tt-v8-masthead #Header1 .img-logo{text-align:center!important}
  .tt-v8-masthead #Header1 img{margin:0 auto!important;max-width:260px!important}
  .tt-v8-masthead > #tt_v8_ad:has(.tt-header-ad-content:empty){display:none!important}
}
/* Remove the old preview opacity and lens-circle entirely. The photo remains clear. */
.index-posts .post-outer .tt-smart-thumb{
  opacity:1!important;
  filter:none!important;
  background:$(tt.hybrid.soft)!important;
  position:relative!important;
  isolation:isolate!important;
}
.index-posts .post-outer .tt-smart-thumb img,
.index-posts .post-outer .tt-smart-thumb:hover img{
  opacity:1!important;filter:none!important;
  transform:none!important;-webkit-transform:none!important;
  transition:none!important;
  object-fit:contain!important;
}
.index-posts .post-outer .tt-smart-thumb .overlay{display:none!important}
.index-posts .post-outer .tt-smart-thumb:after,
.index-posts .post-outer .tt-smart-thumb:hover:after{
  content:none!important;display:none!important;
}
/* Hover call to action on the clickable image; no blur/darken filter on the image. */
.index-posts .post-outer .tt-smart-thumb:before{
  content:'اقرأ الشرح'!important;
  font-family:'Cairo',Tahoma,sans-serif!important;
  font-size:13px!important;font-weight:700!important;
  background:linear-gradient(115deg,$(keycolor),$(step.color))!important;
  color:#fff!important;
  border:0!important;border-radius:8px!important;
  width:auto!important;height:auto!important;
  white-space:nowrap!important;
  line-height:1.5!important;
  padding:9px 18px!important;
  display:block!important;
  position:absolute!important;
  top:50%!important;left:50%!important;right:auto!important;bottom:auto!important;
  margin:0!important;
  transform:translate(-50%,-50%) scale(.94)!important;
  -webkit-transform:translate(-50%,-50%) scale(.94)!important;
  opacity:0!important;visibility:hidden!important;
  pointer-events:none!important;
  z-index:5!important;
  box-shadow:0 4px 14px rgba(0,25,65,.22)!important;
  transition:opacity .18s ease,transform .18s ease!important;
}
.index-posts .post-outer .tt-smart-thumb:hover:before,
.index-posts .post-outer .tt-smart-thumb:focus-visible:before{
  opacity:1!important;visibility:visible!important;
  transform:translate(-50%,-50%) scale(1)!important;
  -webkit-transform:translate(-50%,-50%) scale(1)!important;
}
/* Bottom pagination only: compact, aligned and consistent. */
.more-posts{text-align:center!important;margin:17px auto 11px!important;padding:0!important}
.more-posts a,.more-posts a:hover{
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  font-family:'Cairo',Tahoma,sans-serif!important;
  font-size:13px!important;font-weight:600!important;line-height:1.55!important;
  padding:8px 17px!important;margin:0!important;
  border-radius:7px!important;
  color:#fff!important;
  background:linear-gradient(115deg,$(keycolor),$(step.color))!important;
  box-shadow:0 3px 10px rgba(12,63,140,.11)!important;
  text-decoration:none!important;
  letter-spacing:normal!important;
}
.more-posts a:hover{filter:brightness(.94)!important}
@media(prefers-reduced-motion:reduce){
 .index-posts .post-outer .tt-smart-thumb:before{transition:none!important}
}


/* Techno Tour exact physical header fix — overrides old RTL/grid positioning */
@media screen and (min-width:761px){
  body #tt-v8-masthead{
    position:relative!important;display:block!important;direction:rtl!important;
    background-color:$(tt.hybrid.header)!important;background-image:none!important;
    width:100%!important;min-height:126px!important;
    padding:16px 20px!important;margin:0 auto!important;
    overflow:hidden!important;
  }
  body #tt-v8-masthead > #tt_v8_brand{
    position:absolute!important;display:block!important;
    top:50%!important;right:20px!important;left:auto!important;
    transform:translateY(-50%)!important;
    width:290px!important;max-width:290px!important;
    height:auto!important;min-width:0!important;
    grid-column:auto!important;grid-row:auto!important;
    order:0!important;float:none!important;
    margin:0!important;padding:0!important;
    direction:rtl!important;text-align:right!important;
    background:transparent!important;z-index:3!important;
  }
  body #tt-v8-masthead > #tt_v8_ad{
    position:absolute!important;display:block!important;
    left:20px!important;right:332px!important;
    top:14px!important;bottom:14px!important;
    transform:none!important;
    width:auto!important;max-width:none!important;
    height:auto!important;min-width:0!important;
    grid-column:auto!important;grid-row:auto!important;
    order:1!important;float:none!important;
    margin:0!important;padding:0!important;
    text-align:center!important;direction:rtl!important;
    background-color:$(tt.hybrid.header)!important;
    background-image:none!important;
    z-index:1!important;
  }
}
body #tt-v8-masthead{
 background-color:$(tt.hybrid.header)!important;background-image:none!important;
}
body #tt-v8-masthead #tt_v8_ad,
body #tt-v8-masthead #tt_v8_ad .widget,
body #tt-v8-masthead #tt_v8_ad .widget-content,
body #tt-v8-masthead #tt_v8_ad .tt-header-ad-content{
 background-color:$(tt.hybrid.header)!important;background-image:none!important;
 border:0!important;box-shadow:none!important;
}
body #tt-v8-masthead #tt_v8_ad.tt-v8-ad-is-empty{display:none!important}
body #tt-v8-masthead #Header1,
body #tt-v8-masthead #Header1 .logo,
body #tt-v8-masthead #Header1 .img-logo{
 float:none!important;position:static!important;
 text-align:right!important;direction:rtl!important;margin:0!important;
}
body #tt-v8-masthead #Header1 img{
 display:block!important;margin:0!important;
 max-width:100%!important;max-height:94px!important;object-fit:contain!important;
}
@media screen and (max-width:760px){
 body #tt-v8-masthead{
   display:flex!important;flex-direction:column!important;
   direction:rtl!important;align-items:center!important;
   width:100%!important;max-width:100%!important;
   padding:15px 12px!important;min-height:0!important;
 }
 body #tt-v8-masthead > #tt_v8_brand,
 body #tt-v8-masthead > #tt_v8_ad{
   position:static!important;transform:none!important;
   float:none!important;top:auto!important;right:auto!important;
   bottom:auto!important;left:auto!important;
   width:100%!important;max-width:100%!important;min-height:0!important;
   grid-column:auto!important;grid-row:auto!important;
   margin:0!important;
 }
 body #tt-v8-masthead #Header1,
 body #tt-v8-masthead #Header1 .logo,
 body #tt-v8-masthead #Header1 .img-logo{text-align:center!important}
 body #tt-v8-masthead #Header1 img{margin:0 auto!important}
}


/* Techno Tour V9 — article text buttons and populated footer categories */
.zooming .fa-minus.disb,.zooming .fa-minus[aria-disabled='true']{opacity:.38!important;cursor:not-allowed!important;pointer-events:none!important}
.zooming .fa-plus,.zooming .fa-minus{cursor:pointer!important}
#sec1 .tt-footer-categories{padding:0!important;margin:0!important;list-style:none!important}
#sec1 .tt-footer-categories li{padding:0!important;margin:0!important}
#sec1 .tt-footer-categories a{display:block!important;font-family:'Cairo',Tahoma,Arial,sans-serif!important;font-size:12px!important;font-weight:600!important;line-height:1.7!important;letter-spacing:normal!important;white-space:normal!important;overflow-wrap:anywhere!important;padding:7px 0!important;border-bottom:1px solid $(footer.line)!important}
#sec1 .tt-footer-categories a:hover{color:$(step.color)!important}
@media(max-width:640px){#sec1 .tt-footer-categories a{font-size:12px!important;padding:8px 0!important}}


/* Keep the working original green WhatsApp share button, with WhatsApp glyph. */
.topic-share .social li a.tt-wa-link{background-color:#189d0e!important;color:#ffffff!important;min-width:120px!important}
.topic-share .social li a.tt-wa-link:before{content:'\f232'!important;font-family:FontAwesome!important;color:#ffffff!important}
.topic-share .social li a.tt-wa-link:hover:before{color:#189d0e!important}


/* Techno Tour V11 — sidebar thumbnails render immediately with real src attributes.
   No script / scroll event is required for PopularPosts / FeaturedPost pictures. */
#PopularPosts1 .item-thumbnail img,
#FeaturedPost1 .item-thumbnail img{
 display:block!important;
 opacity:1!important;
 visibility:visible!important;
 filter:none!important;
}


/* Responsive/interactive controls are local to Techno Tour. */
@media(max-width:992px){
  #menu-bar .menu-bar > ul.tt-menu-open{display:block!important}
}
.post-share.tt-share-open .share-menu{display:block!important;opacity:1!important;visibility:visible!important;pointer-events:auto!important}


/* ===== Techno Tour: repair lost sidebar social counters ===== */
#LinkList303 .social-counter li i.fa{
 display:block!important;opacity:1!important;visibility:visible!important;
 font:normal normal normal 23px/55px FontAwesome!important;
 color:#fff!important;text-align:center!important;width:55px!important;
 height:55px!important;
}
#LinkList303 .social-counter li div{
 min-height:25px!important;font-size:11px!important;
 line-height:18px!important;text-align:center!important;
}
/* Restore text alongside article share icons: no hidden zero-sized labels. */
.topic-share .social li a{
 display:flex!important;align-items:center!important;justify-content:center!important;
 gap:7px!important;direction:rtl!important;min-height:40px!important;
 padding:5px 8px!important;
}
.topic-share .social li a:before{
 display:inline-flex!important;align-items:center!important;justify-content:center!important;
 position:static!important;float:none!important;flex:0 0 30px!important;
 width:30px!important;height:30px!important;padding:0!important;
 margin:0!important;line-height:30px!important;
}
.topic-share .social li a b{
 display:inline-block!important;float:none!important;
 width:auto!important;margin:0!important;padding:0!important;
 font:600 13px/1.6 'Cairo',Tahoma,Arial,sans-serif!important;
 color:#fff!important;white-space:nowrap!important;
}
.topic-share .social li a span{display:none!important}
/* The old decorative light-blue stripe at the very top is not navigation. */
.main-container:before{
 content:none!important;display:none!important;height:0!important;
 border:0!important;background:none!important;
}
/* Images are sharp normally; slight blur only under the hover CTA. */
.index-posts .post-outer .tt-smart-thumb img{
 filter:none!important;-webkit-filter:none!important;
 opacity:1!important;transition:filter .2s ease!important;
}
.index-posts .post-outer .tt-smart-thumb:hover img,
.index-posts .post-outer .tt-smart-thumb:focus-visible img{
 filter:blur(1.3px) brightness(.87)!important;
 -webkit-filter:blur(1.3px) brightness(.87)!important;
}
@media(prefers-reduced-motion:reduce){
 .index-posts .post-outer .tt-smart-thumb img{transition:none!important}
}

