body.script:
/* Techno Tour: unobfuscated UI behaviors for navigation, search and shares.
 * Blogger's built-in posts, comments and gadgets remain managed by Blogger. */
(function(){
 'use strict';
 function ready(fn){
   if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',fn);
   else fn();
 }
 ready(function(){
   var menu=document.querySelector('#menu-bar .menu-bar > ul');
   var menuButton=document.querySelector('#menu-bar .menu-bar-res .fa-bars');
   if(menuButton && menu){
     menuButton.setAttribute('role','button');
     menuButton.setAttribute('tabindex','0');
     menuButton.setAttribute('aria-label','فتح قائمة الأقسام');
     function toggleMenu(){
       var opened=menu.classList.toggle('tt-menu-open');
       menuButton.setAttribute('aria-expanded',opened?'true':'false');
     }
     menuButton.addEventListener('click',toggleMenu);
     menuButton.addEventListener('keydown',function(e){
       if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleMenu()}
     });
     document.addEventListener('click',function(e){
       if(!e.target.closest('#menu-bar') && menu.classList.contains('tt-menu-open')){
         menu.classList.remove('tt-menu-open');menuButton.setAttribute('aria-expanded','false');
       }
     });
   }
   var topBtn=document.querySelector('#top-bar .menu-res .fa-bars');
   if(topBtn){
     var topList=document.querySelector('#top-bar .menu-res-wrap ul');
     topBtn.addEventListener('click',function(){
       if(topList)topList.style.display=topList.style.display==='block'?'none':'block';
     });
   }
   document.querySelectorAll('.post-share .share-icon').forEach(function(btn){
     btn.setAttribute('role','button');btn.setAttribute('tabindex','0');
     function toggle(){var p=btn.closest('.post-share');if(p)p.classList.toggle('tt-share-open')}
     btn.addEventListener('click',toggle);
     btn.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}});
   });
   var labels=['','الرئيسية','التالي','السابق','نشر','تغريد','حفظ','مشاركة','إرسال','طباعة','عرض التعليقات فقط','عرض التعليقات والردود','جميع الحقوق محفوظة','حذف التعليق','رد على التعليق','الحجم'];
   document.querySelectorAll('[data-trans]').forEach(function(el){
     var id=Number(el.getAttribute('data-trans'));
     if(labels[id] && !el.textContent.trim())el.textContent=labels[id];
   });
   var top=document.querySelector('.scroll-top');
   if(top)top.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});
 });
})();

/* Techno Tour V7: progressive image fallback. Native Blog thumbnails stay visible without JS. */
(function(){
 'use strict';
 var cache=Object.create(null);
 function grabVideo(text){
  if(!text)return '';
  var patterns=[/(?:youtube(?:-nocookie)?\.com\/(?:embed\/|shorts\/|live\/)|youtu\.be\/)([A-Za-z0-9_-]{11})/i,/(?:youtube\.com\/watch\?(?:[^"'\s<>]*?&(?:amp;)?)*v=)([A-Za-z0-9_-]{11})/i];
  for(var i=0;i<patterns.length;i++){var m=patterns[i].exec(text);if(m)return m[1]}
  return '';
 }
 function articleData(url){
  var u;try{u=new URL(url,location.href);if(u.origin!==location.origin)return Promise.resolve([])}catch(e){return Promise.resolve([])}
  var key=u.origin+u.pathname;
  if(cache[key])return cache[key];
  cache[key]=new Promise(function(resolve){
   var controller=typeof AbortController!=='undefined'?new AbortController():null;
   var timer=setTimeout(function(){if(controller)controller.abort()},13000);
   fetch(u.href,{credentials:'same-origin',signal:controller?controller.signal:undefined}).then(function(resp){if(!resp.ok)throw new Error('HTTP '+resp.status);return resp.text()}).then(function(markup){
    clearTimeout(timer);
    var dom=new DOMParser().parseFromString(markup,'text/html');
    var body=dom.querySelector('.post-body.entry-content')||dom.querySelector('.post-body')||dom.querySelector('article .entry-content');
    if(!body){resolve([]);return}
    var found=[],pics=body.querySelectorAll('img');
    for(var i=0;i<pics.length;i++){
     var img=pics[i],src=img.getAttribute('data-src')||img.getAttribute('data-original')||img.getAttribute('src')||'';
     if(!src||/^data:|\.svg(?:\?|$)|\.gif(?:\?|$)|pixel|avatar|gravatar/i.test(src))continue;
     try{found.push(new URL(src,u.href).href)}catch(e){}
     if(found.length===4)break;
    }
    var video=grabVideo(body.innerHTML);
    if(video){found.push('https://i.ytimg.com/vi/'+video+'/hqdefault.jpg');found.push('https://img.youtube.com/vi/'+video+'/0.jpg')}
    resolve(found);
   }).catch(function(){clearTimeout(timer);resolve([])});
  });
  return cache[key];
 }
 function probe(url){return new Promise(function(done){
  if(!url){done(false);return}
  var test=new Image(),ended=false;
  var timeout=setTimeout(function(){finish(false)},12000);
  function finish(ok){if(ended)return;ended=true;clearTimeout(timeout);test.onload=null;test.onerror=null;done(ok)}
  test.onload=function(){finish(test.naturalWidth>0)};test.onerror=function(){finish(false)};
  test.src=url;if(test.complete)finish(test.naturalWidth>0);
 })}
 function initialize(card){
  if(card.dataset.ttInit==='1')return;card.dataset.ttInit='1';
  var img=card.querySelector('img'),status=card.querySelector('.tt-image-status'),ended=false;
  function setState(state,txt){card.classList.remove('tt-image-loading','tt-image-missing');if(state)card.classList.add(state);if(status&&txt)status.textContent=txt}
  function success(){if(ended)return;ended=true;setState('',null);card.classList.add('tt-image-ready');if(img){img.style.visibility='visible';img.style.opacity='1';img.style.display='block'}}
  function missing(){if(ended)return;ended=true;if(img)img.style.display='none';setState('tt-image-missing','بدون صورة')}
  function recover(){
   if(ended||card.dataset.ttRecover==='1')return;
   card.dataset.ttRecover='1';setState('tt-image-loading','جاري البحث عن صورة...');
   if(img)img.style.display='none';
   var old=img?img.getAttribute('src'):'';
   articleData(card.href||'').then(function(urls){
    urls=urls.filter(function(u,i,a){return u&&u!==old&&a.indexOf(u)===i});
    function next(i){if(i>=urls.length){missing();return}
     probe(urls[i]).then(function(ok){if(!ok){next(i+1);return}
      if(!img){img=document.createElement('img');img.className='notr tt-native-img';img.alt=card.title||'Techno Tour';card.insertBefore(img,card.firstChild)}
      img.onload=success;img.onerror=function(){next(i+1)};
      img.src=urls[i];img.style.display='block';img.style.opacity='1';img.style.visibility='visible';
      if(img.complete&&img.naturalWidth>0)success();
     });
    }
    next(0);
   }).catch(missing);
  }
  if(!img||!img.getAttribute('src')){recover();return}
  // The original image is always visible by CSS. JS is only needed if it fails.
  if(img.complete){if(img.naturalWidth>0)success();else recover()}
  else{
   img.addEventListener('load',success,{once:true});img.addEventListener('error',recover,{once:true});
   setTimeout(function(){if(!ended && !card.dataset.ttRecover && img.complete && img.naturalWidth===0)recover()},19000);
  }
 }
 function start(){
  Array.prototype.forEach.call(document.querySelectorAll('.index-posts .tt-smart-thumb'),initialize);
  // Fix lazy sidebar thumbnails without hiding them when loading or when scripts fail.
  Array.prototype.forEach.call(document.querySelectorAll('#PopularPosts1 .item-thumbnail img'),function(im){
   im.style.display='block';if(!im.getAttribute('src')&&im.getAttribute('data-src'))im.src=im.getAttribute('data-src');
  });
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
 window.addEventListener('load',start,{once:true});
})();
/* Highlight the actual current location in the main Blogger menu. */
(function(){
  function start(){
    var nav=document.querySelector('#menu-bar .menu-bar');if(!nav)return;
    var here=location.pathname.replace(/\/$/,'')||'/';
    try{here=decodeURIComponent(here)}catch(e){}
    var candidates=nav.querySelectorAll('ul > li > a[href]');
    var best=null;
    Array.prototype.forEach.call(candidates,function(a){
      var u;try{u=new URL(a.href,location.href)}catch(e){return}
      if(u.origin!==location.origin)return;
      var path=u.pathname.replace(/\/$/,'')||'/';try{path=decodeURIComponent(path)}catch(e){}
      if(path===here && (!best || a.classList.contains('home')===false))best=a;
    });
    if(best){best.classList.add('tt-current');best.setAttribute('aria-current','page')}
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);
  else start();
})();

/* Individual ad slots controlled via Layout > HTML gadgets. No ads when blank. */
(function(){
  function install(gadgetId,target,kind){
    var source=document.getElementById(gadgetId);
    var template=source && source.querySelector('template.tt-ad-template');
    if(!template || !template.innerHTML.trim())return;
    if(!target)return;
    target.classList.remove('hide');
    target.classList.add('tt-ad-active');
    target.innerHTML='';
    target.appendChild(template.content.cloneNode(true));
    target.setAttribute('data-tt-ad',kind);
  }
  function populate(){
    var body=document.querySelector('.post-body.entry-content');
    if(!body)return;
    install('HTML506',document.querySelector('.Top-Ad'),'top');
    var source=document.getElementById('HTML507');
    var template=source && source.querySelector('template.tt-ad-template');
    if(template && template.innerHTML.trim()){
      var mid=document.querySelector('.Middle-Ad');
      if(!mid){
        mid=document.createElement('div');mid.className='Middle-Ad';
        var paragraphs=body.querySelectorAll('p');
        var anchor=paragraphs[Math.min(2,paragraphs.length-1)];
        if(anchor)anchor.parentNode.insertBefore(mid,anchor.nextSibling);
        else body.appendChild(mid);
      }
      install('HTML507',mid,'middle');
    }
    install('HTML508',document.querySelector('.Bottom-Ad'),'bottom');
  }
  if(document.readyState==='complete')populate();
  else window.addEventListener('load',populate,{once:true});
})();

/* Hide an empty advertisement gadget without affecting AdSense or custom banners. */
(function(){
 function syncHeaderAd(){
  var ad=document.getElementById('tt_v8_ad');
  if(!ad)return;
  var content=ad.querySelector('.tt-header-ad-content');
  var used=!!(content && (content.textContent.trim() || content.querySelector('ins,iframe,img,script,video,svg,object,canvas,a')));
  ad.classList.toggle('tt-v8-ad-is-empty',!used);
 }
 if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',syncHeaderAd)}
 else{syncHeaderAd()}
})();

/* Techno Tour V9: WhatsApp works through the web on desktop and app on mobile. */
function ttWhatsAppShare(event,anchor){
  var shareText=document.title+"\n"+window.location.href;
  var url='https://api.whatsapp.com/send?text='+encodeURIComponent(shareText);
  anchor.href=url;
  anchor.target='_blank';
  anchor.rel='noopener noreferrer';
  /* Browser follows the secure web link; no custom whatsapp:// handler required. */
  return true;
}
/* Techno Tour font zoom — reliable direct controls, original formatting preserved. */
(function(){
  var cache=new WeakMap();
  function articleBody(button){
    var root=button.closest('article') || document;
    return root.querySelector('.post-body.entry-content') || root.querySelector('.post-body') ||
      document.querySelector('.post-body.entry-content') || document.querySelector('.post-body');
  }
  function snapshot(body){
    var list=[body].concat(Array.prototype.slice.call(body.querySelectorAll('*')));
    var rows=[];
    for(var i=0;i<list.length;i++){
      var el=list[i],tag=el.tagName;
      if(!tag || /^(SCRIPT|STYLE|SVG|PATH|IMG|VIDEO|AUDIO|IFRAME|CANVAS|NOSCRIPT|SOURCE|INS|BUTTON|INPUT|FORM|BR|HR|META)$/.test(tag))continue;
      if(el.closest('ins.adsbygoogle,.tt-ad-active,.tt-inline-ad,.Top-Ad,.Bottom-Ad,.Middle-Ad'))continue;
      var size=parseFloat(window.getComputedStyle(el).fontSize);
      if(!isFinite(size)||size<1)continue;
      rows.push({element:el,size:size,inline:el.style.getPropertyValue('font-size'),priority:el.style.getPropertyPriority('font-size')});
    }
    return {level:0,rows:rows};
  }
  function setButtons(group,level){
    if(!group)return;
    var dec=group.querySelector('.fa-minus'),inc=group.querySelector('.fa-plus');
    if(dec){dec.classList.toggle('disb',level===0);dec.setAttribute('aria-disabled',level===0?'true':'false');dec.setAttribute('title',level===0?'الحجم الأصلي':'تصغير الخط')}
    if(inc){inc.setAttribute('title','تكبير الخط');inc.setAttribute('aria-disabled',level>=6?'true':'false')}
  }
  function change(button,amount,event){
    if(event){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation()}
    var group=button.closest('.zooming');
    var body=articleBody(button);
    if(!body || !group)return false;
    var state=cache.get(body);
    if(!state){state=snapshot(body);cache.set(body,state)}
    state.level=Math.max(0,Math.min(6,state.level+amount));
    var level=state.level;
    for(var i=0;i<state.rows.length;i++){
      var row=state.rows[i];
      if(!row.element.isConnected)continue;
      if(level===0){
        if(row.inline)row.element.style.setProperty('font-size',row.inline,row.priority);
        else row.element.style.removeProperty('font-size');
      }else{
        row.element.style.setProperty('font-size',(row.size+level*2)+'px','important');
      }
    }
    setButtons(group,level);
    return false;
  }
  window.ttZoomArticleText=change;
  /* Capture at window before legacy theme's delegated handlers can adjust line-height. */
  window.addEventListener('click',function(ev){
    var target=ev.target;
    var control=target.closest&&target.closest('.zooming .fa-plus,.zooming .fa-minus');
    if(!control)return;
    change(control,control.classList.contains('fa-plus')?1:-1,ev);
  },true);
  window.addEventListener('keydown',function(ev){
    var target=ev.target,control=target.closest&&target.closest('.zooming .fa-plus,.zooming .fa-minus');
    if(!control || (ev.key!=='Enter'&&ev.key!==' '))return;
    change(control,control.classList.contains('fa-plus')?1:-1,ev);
  },true);
  function ready(){
    var groups=document.querySelectorAll('.zooming');
    for(var i=0;i<groups.length;i++){
      var group=groups[i],buttons=group.querySelectorAll('.fa-plus,.fa-minus');
      setButtons(group,0);
      for(var j=0;j<buttons.length;j++){buttons[j].setAttribute('role','button');buttons[j].setAttribute('tabindex','0')}
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);
  else ready();
})();

/* Techno Tour: interpret user-editable LinkList names as network-count. */
(function(){
 'use strict';
 var networks={
  facebook:'facebook',twitter:'twitter',linkedin:'linkedin',
  rss:'rss',youtube:'youtube',instagram:'instagram',
  snapchat:'snapchat',pinterest:'pinterest',
  telegram:'telegram',tiktok:'music',whatsapp:'whatsapp',
  threads:'at'
 };
 function renderCounters(){
  var rows=document.querySelectorAll('#LinkList303 .social-counter li');
  for(var i=0;i<rows.length;i++){
   var row=rows[i],icon=row.querySelector('i[data-site]');
   if(!icon)continue;
   var raw=(icon.getAttribute('data-site')||'').trim();
   var match=/^(.+?)(?:-([0-9][0-9,\s]*))?$/.exec(raw);
   var network=match?match[1].toLowerCase().trim():raw.toLowerCase();
   var count=match&&match[2]?match[2].replace(/\s/g,''):'';
   var cssName=networks[network]||'globe';
   icon.className='fa fa-'+cssName;
   icon.setAttribute('aria-hidden','true');
   var link=row.querySelector('a'),counter=row.querySelector('div');
   if(link)link.setAttribute('aria-label',network+(count?' '+count:''));
   if(counter)counter.textContent=count;
  }
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',renderCounters);
 else renderCounters();
})();
